          "id": "a3_s3_c71",
          "speaker": "Maddalena e Sparafucile",
          "stageDirection": "Sparafucile va a postarsi con un pugnale dietro alla porta; Maddalena apre e poi corre a chiudere la grande arcata di fronte, mentre entra Gilda, dietro a cui Sparafucile chiude la porta, e tutto resta sepolto nel silenzio e nel buio.",
          "stageDirectionTranslation": "Sparafucile goes to stand behind the door with a dagger; Maddalena opens and then runs to close the large arch in front, while Gilda enters, behind whom Sparafucile closes the door, and everything remains buried in silence and darkness.",
